int64_t clock_us(void){LARGE_INTEGER t,f;QueryPerformanceCounter(&t);QueryPerformanceFrequency(&f);return t.QuadPart*1000000/f.QuadPart;}int64_t wall_ms(void){FILETIME f;ULARGE_INTEGER u;GetSystemTimeAsFileTime(&f);u.LowPart=f.dwLowDateTime;u.HighPart=f.dwHighDateTime;return u.QuadPart/10000-11644473600000LL;}
char*make_key(const char*kind,const char*id){J*a=cJSON_CreateArray();cJSON_AddItemToArray(a,cJSON_CreateString(kind));cJSON_AddItemToArray(a,cJSON_CreateString(id));char*k=json(a);cJSON_Delete(a);return k;}
static wchar_t*normal(const char*s){wchar_t*w=wide(s);int n=NormalizeString(NormalizationKC,w,-1,0,0);if(n>0){wchar_t*t=calloc(n+2,2);NormalizeString(NormalizationKC,w,-1,t,n+1);free(w);w=t;}CharLowerBuffW(w,(DWORD)wcslen(w));return w;}
static void normal_sql(sqlite3_context*c,int argc,sqlite3_value**argv){wchar_t*w=normal((char*)sqlite3_value_text(argv[0]));char*t=utf8(w);free(w);sqlite3_result_text(c,t,-1,free);}
typedef struct{wchar_t*buffer,*terms[64];int count;} SearchTerms;
static void terms_free(void*p){SearchTerms*t=p;if(t){free(t->buffer);free(t);}}
static void match_sql(sqlite3_context*c,int argc,sqlite3_value**argv){const char*s=(char*)sqlite3_value_text(argv[0]),*q=(char*)sqlite3_value_text(argv[1]);if(!q||!*q){sqlite3_result_int(c,1);return;}SearchTerms*t=sqlite3_get_auxdata(c,1);int fresh=!t;if(!t){t=calloc(1,sizeof(*t));t->buffer=normal(q);wchar_t*ctx=0,*p=wcstok_s(t->buffer,L" \t\r\n",&ctx);while(p&&t->count<64){t->terms[t->count++]=p;p=wcstok_s(0,L" \t\r\n",&ctx);}}wchar_t*hay=normal(s?s:"");int ok=1;for(int i=0;i<t->count;i++)if(!wcsstr(hay,t->terms[i])){ok=0;break;}free(hay);sqlite3_result_int(c,ok);if(fresh)sqlite3_set_auxdata(c,1,t,terms_free);}
int ui_query_init(DB*d){sqlite3_create_function_v2(d->sql,"gx_normal",1,SQLITE_UTF8|SQLITE_DETERMINISTIC,0,normal_sql,0,0,0);sqlite3_create_function_v2(d->sql,"gx_match",2,SQLITE_UTF8|SQLITE_DETERMINISTIC,0,match_sql,0,0,0);const char*sql="DROP TRIGGER IF EXISTS native_search_insert; DROP TRIGGER IF EXISTS native_search_update; CREATE INDEX IF NOT EXISTS native_entity_id ON entities(kind,id,deleted); CREATE INDEX IF NOT EXISTS native_board_count ON entities(kind,deleted,quadrant,done,parent_id,start); CREATE INDEX IF NOT EXISTS native_order ON entities(kind,deleted,quadrant,done,start,json_extract(data,'$.order')); CREATE INDEX IF NOT EXISTS native_time ON entities(kind,deleted,quadrant,done,CASE WHEN start='' THEN '9999' ELSE start END,json_extract(data,'$.createdAt'),key); CREATE INDEX IF NOT EXISTS native_manual ON entities(kind,deleted,quadrant,coalesce(json_extract(data,'$.order'),0),key); CREATE INDEX IF NOT EXISTS native_project ON entities(kind,deleted,json_extract(data,'$.project')); CREATE INDEX IF NOT EXISTS native_place ON entities(kind,deleted,json_extract(data,'$.place')); CREATE INDEX IF NOT EXISTS native_neighbors ON entities(kind,deleted,parent_id,quadrant,coalesce(json_extract(data,'$.order'),0),key); CREATE INDEX IF NOT EXISTS native_child_order ON entities(kind,deleted,parent_id,coalesce(json_extract(data,'$.order'),0),key); CREATE INDEX IF NOT EXISTS native_children ON entities(kind,deleted,parent_id,json_extract(data,'$.order')); CREATE TABLE IF NOT EXISTS native_search(key TEXT PRIMARY KEY,text TEXT NOT NULL); CREATE TABLE IF NOT EXISTS native_search_normal(key TEXT PRIMARY KEY,text TEXT NOT NULL); CREATE TABLE IF NOT EXISTS native_search_dirty(key TEXT PRIMARY KEY); CREATE TABLE IF NOT EXISTS native_index_meta(version INTEGER NOT NULL); DELETE FROM native_search_normal WHERE NOT EXISTS(SELECT 1 FROM native_index_meta WHERE version=4); CREATE TRIGGER IF NOT EXISTS native_search_insert AFTER INSERT ON entities BEGIN DELETE FROM native_search_normal WHERE key IN( WITH RECURSIVE ancestors(id) AS(SELECT new.id UNION SELECT e.parent_id FROM ancestors a CROSS JOIN entities e INDEXED BY native_entity_id ON e.id=a.id WHERE e.kind='tasks' AND e.parent_id IS NOT NULL) SELECT key FROM entities INDEXED BY native_entity_id WHERE kind='tasks' AND id IN ancestors); DELETE FROM native_search_dirty WHERE key IN( WITH RECURSIVE ancestors(id) AS(SELECT new.id UNION SELECT e.parent_id FROM ancestors a CROSS JOIN entities e INDEXED BY native_entity_id ON e.id=a.id WHERE e.kind='tasks' AND e.parent_id IS NOT NULL) SELECT key FROM entities INDEXED BY native_entity_id WHERE kind='tasks' AND id IN ancestors); INSERT INTO native_search_dirty SELECT key FROM entities WHERE key IN( WITH RECURSIVE ancestors(id) AS(SELECT new.id UNION SELECT e.parent_id FROM ancestors a CROSS JOIN entities e INDEXED BY native_entity_id ON e.id=a.id WHERE e.kind='tasks' AND e.parent_id IS NOT NULL) SELECT key FROM entities INDEXED BY native_entity_id WHERE kind='tasks' AND id IN ancestors); DELETE FROM native_search_dirty WHERE key=new.key; INSERT INTO native_search_dirty VALUES(new.key); DELETE FROM native_search_normal WHERE key=new.key; DELETE FROM native_search WHERE key=new.key; INSERT INTO native_search VALUES(new.key,coalesce(json_extract(new.data,'$.title'),'')||' '||coalesce(json_extract(new.data,'$.body'),'')||' '||coalesce(json_extract(new.data,'$.name'),'')||' '||coalesce(json_extract(new.data,'$.description'),'')||' '||coalesce(json_extract(new.data,'$.notes'),'')||' '||coalesce(json_extract(new.data,'$.review'),'')||' '||coalesce(json_extract(new.data,'$.project'),'')||' '||coalesce(json_extract(new.data,'$.place'),'')||' '||coalesce(json_extract(new.data,'$.tags'),'')||' '||coalesce(json_extract(new.data,'$.start'),'')||' '||coalesce(json_extract(new.data,'$.end'),'')||CASE WHEN new.done=1 THEN ' 已完成' ELSE ' 未完成' END||CASE WHEN json_type(new.data,'$.repeat')='object' THEN ' 重复' ELSE '' END||CASE WHEN json_type(new.data,'$.reminder')='object' THEN ' 提醒' ELSE '' END); END; CREATE TRIGGER IF NOT EXISTS native_search_update AFTER UPDATE OF data ON entities BEGIN DELETE FROM native_search_normal WHERE key IN( WITH RECURSIVE ancestors(id) AS(SELECT new.id UNION SELECT e.parent_id FROM ancestors a CROSS JOIN entities e INDEXED BY native_entity_id ON e.id=a.id WHERE e.kind='tasks' AND e.parent_id IS NOT NULL) SELECT key FROM entities INDEXED BY native_entity_id WHERE kind='tasks' AND id IN ancestors); DELETE FROM native_search_dirty WHERE key IN( WITH RECURSIVE ancestors(id) AS(SELECT new.id UNION SELECT e.parent_id FROM ancestors a CROSS JOIN entities e INDEXED BY native_entity_id ON e.id=a.id WHERE e.kind='tasks' AND e.parent_id IS NOT NULL) SELECT key FROM entities INDEXED BY native_entity_id WHERE kind='tasks' AND id IN ancestors); INSERT INTO native_search_dirty SELECT key FROM entities WHERE key IN( WITH RECURSIVE ancestors(id) AS(SELECT new.id UNION SELECT e.parent_id FROM ancestors a CROSS JOIN entities e INDEXED BY native_entity_id ON e.id=a.id WHERE e.kind='tasks' AND e.parent_id IS NOT NULL) SELECT key FROM entities INDEXED BY native_entity_id WHERE kind='tasks' AND id IN ancestors); DELETE FROM native_search_dirty WHERE key=new.key; INSERT INTO native_search_dirty VALUES(new.key); DELETE FROM native_search_normal WHERE key=new.key; DELETE FROM native_search WHERE key=new.key; INSERT INTO native_search VALUES(new.key,coalesce(json_extract(new.data,'$.title'),'')||' '||coalesce(json_extract(new.data,'$.body'),'')||' '||coalesce(json_extract(new.data,'$.name'),'')||' '||coalesce(json_extract(new.data,'$.description'),'')||' '||coalesce(json_extract(new.data,'$.notes'),'')||' '||coalesce(json_extract(new.data,'$.review'),'')||' '||coalesce(json_extract(new.data,'$.project'),'')||' '||coalesce(json_extract(new.data,'$.place'),'')||' '||coalesce(json_extract(new.data,'$.tags'),'')||' '||coalesce(json_extract(new.data,'$.start'),'')||' '||coalesce(json_extract(new.data,'$.end'),'')||CASE WHEN new.done=1 THEN ' 已完成' ELSE ' 未完成' END||CASE WHEN json_type(new.data,'$.repeat')='object' THEN ' 重复' ELSE '' END||CASE WHEN json_type(new.data,'$.reminder')='object' THEN ' 提醒' ELSE '' END); END; INSERT OR REPLACE INTO native_search SELECT key,coalesce(json_extract(data,'$.title'),'')||' '||coalesce(json_extract(data,'$.body'),'')||' '||coalesce(json_extract(data,'$.name'),'')||' '||coalesce(json_extract(data,'$.description'),'')||' '||coalesce(json_extract(data,'$.notes'),'')||' '||coalesce(json_extract(data,'$.review'),'')||' '||coalesce(json_extract(data,'$.project'),'')||' '||coalesce(json_extract(data,'$.place'),'')||' '||coalesce(json_extract(data,'$.tags'),'')||' '||coalesce(json_extract(data,'$.start'),'')||' '||coalesce(json_extract(data,'$.end'),'')||CASE WHEN done=1 THEN ' 已完成' ELSE ' 未完成' END||CASE WHEN json_type(data,'$.repeat')='object' THEN ' 重复' ELSE '' END||CASE WHEN json_type(data,'$.reminder')='object' THEN ' 提醒' ELSE '' END FROM entities WHERE NOT EXISTS(SELECT 1 FROM native_index_meta WHERE version=4); INSERT OR IGNORE INTO native_search_dirty SELECT key FROM native_search s WHERE NOT EXISTS(SELECT 1 FROM native_search_normal n WHERE n.key=s.key); DELETE FROM native_search_normal WHERE key IN(SELECT key FROM entities WHERE deleted=1); DELETE FROM native_index_meta; INSERT INTO native_index_meta VALUES(4); INSERT INTO native_search_normal SELECT s.key,gx_normal(s.text||CASE WHEN e.kind='tasks' AND EXISTS(SELECT 1 FROM entities child WHERE child.kind='tasks' AND child.deleted=0 AND child.parent_id=e.id) THEN coalesce((WITH RECURSIVE tree(id) AS(SELECT e.id UNION SELECT child.id FROM entities child JOIN tree t ON child.parent_id=t.id WHERE child.kind='tasks' AND child.deleted=0) SELECT group_concat(childSearch.text,' ') FROM entities child JOIN native_search childSearch ON childSearch.key=child.key WHERE child.kind='tasks' AND child.deleted=0 AND child.id IN tree),'') ELSE '' END) FROM native_search_dirty dirty CROSS JOIN native_search s ON s.key=dirty.key CROSS JOIN entities e ON e.key=s.key WHERE e.deleted=0; DELETE FROM native_search_dirty;";char*err=0;int ok=sqlite3_exec(d->sql,sql,0,0,&err)==SQLITE_OK;if(!ok)snprintf(d->error,sizeof(d->error),"%s",err?err:"Index creation failed");sqlite3_free(err);return ok;}
static void range(const Filter*f,char*a,char*b){strcpy(a,f->date);strcpy(b,f->date);char stamp[32];sprintf(stamp,"%sT12:00",f->date);int64_t n=time_ms(stamp);if(f->period==1){ULARGE_INTEGER u;u.QuadPart=(n+11644473600000LL+28800000)*10000;FILETIME ft={u.LowPart,u.HighPart};SYSTEMTIME t;FileTimeToSystemTime(&ft,&t);int shift=(t.wDayOfWeek+6)%7;format_ms(n-shift*86400000LL,a);format_ms(n+(6-shift)*86400000LL,b);a[10]=b[10]=0;}else if(f->period==2){a[8]='0';a[9]='1';int y,m,d;sscanf(b,"%d-%d-%d",&y,&m,&d);int days[]={31,28,31,30,31,30,31,31,30,31,30,31};d=days[m-1]+(m==2&&!(y%4)&&(y%100||!(y%400)));sprintf(b,"%04d-%02d-%02d",y,m,d);}}
static sqlite3_stmt*prepare(DB*d,const Filter*f,int first,int limit,int count){if(*f->query){char*err=0;if(sqlite3_exec(d->sql,"BEGIN IMMEDIATE; INSERT INTO native_search_normal SELECT s.key,gx_normal(s.text||CASE WHEN e.kind='tasks' AND EXISTS(SELECT 1 FROM entities child WHERE child.kind='tasks' AND child.deleted=0 AND child.parent_id=e.id) THEN coalesce((WITH RECURSIVE tree(id) AS(SELECT e.id UNION SELECT child.id FROM entities child JOIN tree t ON child.parent_id=t.id WHERE child.kind='tasks' AND child.deleted=0) SELECT group_concat(childSearch.text,' ') FROM entities child JOIN native_search childSearch ON childSearch.key=child.key WHERE child.kind='tasks' AND child.deleted=0 AND child.id IN tree),'') ELSE '' END) FROM native_search_dirty dirty CROSS JOIN native_search s ON s.key=dirty.key CROSS JOIN entities e ON e.key=s.key WHERE e.deleted=0; DELETE FROM native_search_dirty; COMMIT",0,0,&err)!=SQLITE_OK){snprintf(d->error,sizeof(d->error),"%s",err?err:"Search cache failed");sqlite3_free(err);sqlite3_exec(d->sql,"ROLLBACK",0,0,0);return 0;}}int global=!strcmp(f->kind,"search");char sql[8000]="SELECT ";strcat(sql,count?"count(*)":global?"s.key,(SELECT data FROM entities e WHERE e.key=s.key)":"e.key,e.data");if(global)strcat(sql," FROM native_search_normal s WHERE 1 ");else{if(*f->query)strcat(sql," FROM native_search_normal s CROSS JOIN entities e ON e.key=s.key ");else strcat(sql," FROM entities e ");strcat(sql,"WHERE e.deleted=0 ");}if(global&&!*f->query)strcat(sql,"AND 0 ");if(strcmp(f->kind,"search"))strcat(sql,"AND e.kind=:kind ");if(!strcmp(f->kind,"tasks")){if(f->status!=2)strcat(sql,"AND e.done=:status ");if(f->quadrant!=-1)strcat(sql,"AND e.quadrant=:q ");if(*f->parent)strcat(sql,"AND e.parent_id=:parent ");else if(f->quadrant!=-1&&!strcmp(f->kind,"tasks")&&!*f->query)strcat(sql,"AND (e.parent_id IS NULL OR NOT EXISTS(SELECT 1 FROM entities p WHERE p.kind='tasks' AND p.id=e.parent_id AND p.deleted=0)) ");if(f->period!=3&&!*f->parent)strcat(sql,"AND (e.start='' OR (e.start<:end AND (e.done=0 OR e.start>=:begin))) AND (coalesce(json_extract(e.data,'$.repeat.until'),'')='' OR json_extract(e.data,'$.repeat.until')>=:begin) ");}
 if(!strcmp(f->kind,"projects")&&f->archive>=0)strcat(sql,"AND coalesce(json_extract(e.data,'$.archived'),0)=:archive ");
 if(!strcmp(f->groupKind,"project"))strcat(sql,"AND json_extract(e.data,'$.project')=:group ");else if(!strcmp(f->groupKind,"place"))strcat(sql,"AND json_extract(e.data,'$.place')=:group ");else if(!strcmp(f->groupKind,"tag"))strcat(sql,"AND EXISTS(SELECT 1 FROM json_each(e.data,'$.tags') WHERE value=:group) ");wchar_t*terms=normal(f->query),*ctx=0,*term=wcstok_s(terms,L" \t\r\n",&ctx);char*normalizedTerms[64]={0};int termCount=0;while(term&&termCount<64){char clause[60];snprintf(clause,sizeof(clause),"AND instr(s.text,:t%d)>0 ",termCount);strcat(sql,clause);normalizedTerms[termCount++]=utf8(term);term=wcstok_s(0,L" \t\r\n",&ctx);}free(terms);if(!count){if(!strcmp(f->kind,"tasks"))strcat(sql,f->manual?"ORDER BY coalesce(json_extract(e.data,'$.order'),0),e.key ":"ORDER BY e.done,CASE WHEN e.start='' THEN '9999' ELSE e.start END,json_extract(e.data,'$.createdAt'),e.key ");else if(!strcmp(f->kind,"notes"))strcat(sql,"ORDER BY json_extract(e.data,'$.createdAt') DESC,e.key ");else strcat(sql,global?"ORDER BY s.key ":"ORDER BY e.kind,json_extract(e.data,'$.name'),e.key ");strcat(sql,"LIMIT :limit OFFSET :offset");}sqlite3_stmt*s=0;if(sqlite3_prepare_v2(d->sql,sql,-1,&s,0)!=SQLITE_OK){for(int i=0;i<termCount;i++)free(normalizedTerms[i]);snprintf(d->error,sizeof(d->error),"%s",sqlite3_errmsg(d->sql));return 0;}sqlite3_bind_text(s,sqlite3_bind_parameter_index(s,":kind"),f->kind,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,sqlite3_bind_parameter_index(s,":status"),f->status);sqlite3_bind_int(s,sqlite3_bind_parameter_index(s,":archive"),f->archive);sqlite3_bind_int(s,sqlite3_bind_parameter_index(s,":q"),f->quadrant);sqlite3_bind_text(s,sqlite3_bind_parameter_index(s,":parent"),f->parent,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,sqlite3_bind_parameter_index(s,":group"),f->group,-1,SQLITE_TRANSIENT);for(int i=0;i<termCount;i++){char name[16];snprintf(name,sizeof(name),":t%d",i);sqlite3_bind_text(s,sqlite3_bind_parameter_index(s,name),normalizedTerms[i],-1,SQLITE_TRANSIENT);free(normalizedTerms[i]);}char a[32],b[32];range(f,a,b);strcat(b,"~");sqlite3_bind_text(s,sqlite3_bind_parameter_index(s,":begin"),a,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,sqlite3_bind_parameter_index(s,":end"),b,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,sqlite3_bind_parameter_index(s,":limit"),limit);sqlite3_bind_int(s,sqlite3_bind_parameter_index(s,":offset"),first);return s;}
int query_count(DB*d,const Filter*f){sqlite3_stmt*s=prepare(d,f,0,0,1);if(!s)return 0;int n=sqlite3_step(s)==SQLITE_ROW?sqlite3_column_int(s,0):0;sqlite3_finalize(s);return n;}
J*query_rows(DB*d,const Filter*f,int first,int limit){J*a=cJSON_CreateArray();sqlite3_stmt*s=prepare(d,f,first,limit,0);if(!s)return a;while(sqlite3_step(s)==SQLITE_ROW){J*r=cJSON_CreateObject();ss(r,"key",(char*)sqlite3_column_text(s,0));J*t=cJSON_Parse((char*)sqlite3_column_text(s,1));if(!strcmp(f->kind,"projects")||!strcmp(f->kind,"places")||!strcmp(f->kind,"tags")){sqlite3_stmt*stats=0;const char*sql=!strcmp(f->kind,"tags")?"SELECT count(*),coalesce(sum(done),0) FROM entities e WHERE e.kind='tasks' AND e.deleted=0 AND EXISTS(SELECT 1 FROM json_each(e.data,'$.tags') WHERE value=?)":!strcmp(f->kind,"places")?"SELECT count(*),coalesce(sum(done),0) FROM entities WHERE kind='tasks' AND deleted=0 AND json_extract(data,'$.place')=?":"SELECT count(*),coalesce(sum(done),0) FROM entities WHERE kind='tasks' AND deleted=0 AND json_extract(data,'$.project')=?";if(sqlite3_prepare_v2(d->sql,sql,-1,&stats,0)==SQLITE_OK){sqlite3_bind_text(stats,1,str(t,"name"),-1,SQLITE_TRANSIENT);if(sqlite3_step(stats)==SQLITE_ROW){sn(t,"_nativeTotal",sqlite3_column_int(stats,0));sn(t,"_nativeDone",sqlite3_column_int(stats,1));}}sqlite3_finalize(stats);}set(r,"data",t);cJSON_AddItemToArray(a,r);}sqlite3_finalize(s);return a;}
